css:
body{margin:0;font:12px/1.45 var(--pad-font);color:var(--pad-fg);-webkit-font-smoothing:antialiased}
.panel{display:flex;flex-direction:column;gap:16px;padding:4px 2px}

.meta{display:flex;align-items:center;gap:8px;font-size:10.5px;line-height:1;color:var(--pad-fg-3)}
.repo{font-family:var(--pad-mono);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.tag{flex:none;padding:1px 6px;border-radius:3px;background:var(--pad-bg-2);font-family:var(--pad-mono);font-variant-numeric:tabular-nums}
.refresh{margin-left:auto;flex:none;display:grid;place-items:center;width:24px;height:24px;padding:0;border:1px solid var(--pad-border);border-radius:6px;background:none;color:var(--pad-fg-3);cursor:pointer}
.refresh:hover{color:var(--pad-fg);border-color:var(--pad-fg-3)}
.refresh:focus-visible{outline:2px solid var(--pad-accent);outline-offset:2px}
.refresh svg{width:12px;height:12px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}

.stat{display:flex;flex-direction:column;gap:2px}
.stat b{font-size:28px;line-height:1.1;font-weight:650;letter-spacing:-.02em;font-variant-numeric:tabular-nums}
.qualifier{font-size:11px;line-height:1.35;color:var(--pad-fg-3)}
.spark{margin-top:8px;line-height:0}
.spark svg{display:block;width:100%;height:28px;overflow:visible}

.facts{display:flex;flex-wrap:wrap;gap:4px 14px;font-size:10.5px;line-height:1.4;color:var(--pad-fg-3)}
.facts b{color:var(--pad-fg-2);font-weight:600;font-variant-numeric:tabular-nums}

.note{margin:0;padding-left:8px;border-left:2px solid var(--pad-danger);font-size:11px;line-height:1.5;color:var(--pad-danger)}

.section{display:flex;flex-direction:column;gap:6px}
.head{display:flex;align-items:baseline;gap:8px}
.head h2{margin:0;font-size:11px;line-height:1.4;font-weight:600;color:var(--pad-fg-2)}
.head em{font-style:normal;margin-left:auto;font-size:10px;color:var(--pad-fg-3);font-variant-numeric:tabular-nums}
.rows{display:flex;flex-direction:column}

.row{display:grid;grid-template-columns:auto minmax(0,1fr);gap:1px 8px;width:100%;margin:0;padding:6px 0;border:0;border-top:1px solid var(--pad-border);background:none;text-align:left;font:inherit;color:inherit;cursor:pointer}
.row:first-child{border-top:0;padding-top:2px}
.row:hover .title{color:var(--pad-accent)}
.row:focus-visible{outline:2px solid var(--pad-accent);outline-offset:-2px;border-radius:6px}
.num{font-family:var(--pad-mono);font-size:10px;line-height:1.6;color:var(--pad-fg-3);font-variant-numeric:tabular-nums}
.title{font-size:12px;line-height:1.4;color:var(--pad-fg-2);overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}
.sub{grid-column:1/-1;display:flex;flex-wrap:wrap;align-items:center;gap:5px;font-size:10px;line-height:1.5;color:var(--pad-fg-3);font-variant-numeric:tabular-nums}

.chip{padding:0 4px;border-radius:3px;border:1px solid var(--pad-border);font-family:var(--pad-mono);font-size:10px;line-height:15px;color:var(--pad-fg-3);white-space:nowrap}
.chip.ok{border-color:var(--pad-ok);color:var(--pad-ok)}
.chip.warn{border-color:var(--pad-warn);color:var(--pad-warn)}
.chip.bad{border-color:var(--pad-danger);color:var(--pad-danger)}

.empty{margin:0;padding:6px 0 2px;border-top:1px solid var(--pad-border);font-size:11px;line-height:1.5;color:var(--pad-fg-3)}
.foot{display:flex;align-items:center;gap:8px;padding-top:10px;border-top:1px solid var(--pad-border);font-size:10px;line-height:1.4;color:var(--pad-fg-3)}
.link{margin-left:auto;padding:0;border:0;background:none;font:inherit;color:var(--pad-accent);cursor:pointer}
.link:hover{text-decoration:underline}
.link:focus-visible{outline:2px solid var(--pad-accent);outline-offset:2px}

@media (prefers-reduced-motion: reduce){*{transition:none!important;animation:none!important}}

script:
var $ = function (id) { return document.getElementById(id) }
var REPO = 'https://github.com/ChisaAlter/WhaleIsle'

function esc(v) { return dsh.escape(v == null ? '' : String(v)) }
function num(v) { if (v == null || v === '') return null; var n = Number(v); return isFinite(n) ? n : null }
function fmt(n) { return n == null ? '—' : dsh.fmt.number(n, 0) }
// Restored readings can arrive as JSON text rather than parsed JSON.
function obj(v) {
  if (typeof v !== 'string') return v
  try { return JSON.parse(v) } catch (e) { return null }
}
function read(S, id) {
  var r = S[id]
  if (!r || !r.ok) return null
  var value = obj(r.value)
  return value == null ? null : value
}

// Sparkline: a time series riding inside the card carries no axes or grid.
function sparkline(values) {
  if (!values || values.length < 2) return ''
  var pts = values.map(function (v) { return Number(v) || 0 })
  var max = Math.max.apply(null, pts), min = Math.min.apply(null, pts)
  var span = max - min || 1
  var w = 100, h = 26, dw = 1.6
  var d = ''
  for (var i = 0; i < pts.length; i++) {
    var x = (i / (pts.length - 1)) * (w - dw)
    var y = h - ((pts[i] - min) / span) * (h - 3) - 1.5
    d += (i === 0 ? 'M' : 'L') + x.toFixed(2) + ' ' + y.toFixed(2)
  }
  var area = d + 'L' + (w - dw).toFixed(2) + ' ' + h + 'L0 ' + h + 'Z'
  return '<svg viewBox="0 0 100 26" preserveAspectRatio="none" aria-hidden="true">' +
    '<path d="' + area + '" fill="var(--pad-accent)" opacity=".12"/>' +
    '<path d="' + d + '" fill="none" stroke="var(--pad-accent)" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke"/>' +
  '</svg>'
}

function chips(o) {
  var out = []
  if (o.dr) out.push('<span class="chip">草稿</span>')
  if (o.rv === 'APPROVED') out.push('<span class="chip ok">已批准</span>')
  if (o.rv === 'CHANGES_REQUESTED') out.push('<span class="chip bad">待修改</span>')
  if (o.mg === 'CONFLICTING') out.push('<span class="chip bad">冲突</span>')
  return out.join('')
}

function row(o, closed) {
  var sub = closed ? '<span class="chip">已关闭</span>' : chips(o)
  if (o.u) sub += '<span>' + esc(dsh.fmt.ago(o.u)) + '</span>'
  if (o.cm) sub += '<span>' + esc(o.cm) + ' 条评论</span>'
  return '<button type="button" class="row" data-url="' + esc(o.url) + '">' +
    '<span class="num">#' + esc(o.n) + '</span>' +
    '<span class="title">' + esc(o.t) + '</span>' +
    '<span class="sub">' + sub + '</span>' +
  '</button>'
}

function render(data) {
  var S = (data && data.sources) || {}
  var repo = read(S, 'repo')
  var part = read(S, 'part')
  var prs = read(S, 'prs')
  var issues = read(S, 'issues')
  var counts = read(S, 'counts')
  var release = read(S, 'release')

  $('tag').textContent = release && release.tag ? release.tag : 'v—'
  $('star').textContent = fmt(repo ? num(repo.stars) : null)
  $('fork').textContent = fmt(repo ? num(repo.forks) : null)
  $('merged').textContent = counts && counts.length ? fmt(num(counts[0])) : '—'

  var weeks = part && part.all ? part.all.slice(-12) : []
  var total = 0
  for (var i = 0; i < weeks.length; i++) total += Number(weeks[i]) || 0
  $('commits').textContent = weeks.length ? fmt(total) : '—'
  $('spark').innerHTML = weeks.length ? sparkline(weeks) : ''

  var hasPrs = Array.isArray(prs)
  if (!hasPrs) {
    $('prs').innerHTML = '<p class="empty">这部分没取到</p>'
    $('prn').textContent = ''
  } else if (!prs.length) {
    $('prs').innerHTML = '<p class="empty">没有待处理的 PR</p>'
    $('prn').textContent = ''
  } else {
    $('prs').innerHTML = prs.slice(0, 3).map(function (o) { return row(o, false) }).join('')
    $('prn').textContent = prs.length > 3 ? '还有 ' + (prs.length - 3) + ' 个' : ''
  }

  var hasIssues = Array.isArray(issues)
  if (!hasIssues) {
    $('iss').innerHTML = '<p class="empty">这部分没取到</p>'
    $('issmeta').textContent = ''
  } else if (!issues.length) {
    $('iss').innerHTML = '<p class="empty">还没有 Issue</p>'
    $('issmeta').textContent = ''
  } else {
    $('iss').innerHTML = issues.slice(0, 3).map(function (o) { return row(o, true) }).join('')
    $('issmeta').textContent = counts && counts.length ? (num(counts[2]) || 0) + ' 开放 · ' + fmt(num(counts[1])) + ' 已关' : ''
  }

  var keys = Object.keys(S)
  var live = keys.filter(function (k) { return S[k] && S[k].ok })
  if (keys.length && !live.length) {
    $('err').hidden = false
    $('err').textContent = '数据源全部失败：' + String((S[keys[0]] && S[keys[0]].error) || '未知错误').slice(0, 80)
  } else {
    $('err').hidden = true
  }

  var stamps = live.map(function (k) { return S[k].at }).filter(Boolean).sort()
  $('up').textContent = stamps.length ? '更新于 ' + dsh.fmt.ago(stamps[stamps.length - 1]) : '尚未取数'
}

dsh.onData(render)

function open(url) { if (url) dsh.openUrl(url) }
$('lk').addEventListener('click', function () { open(REPO) })
$('rf').addEventListener('click', function () {
  $('rf').disabled = true
  dsh.refresh()
  setTimeout(function () { $('rf').disabled = false }, 1200)
})
;['prs', 'iss'].forEach(function (id) {
  $(id).addEventListener('click', function (e) {
    var hit = e.target && e.target.closest ? e.target.closest('.row') : null
    if (hit) open(hit.getAttribute('data-url'))
  })
})
